$addButtonPeriod=document.getElementById("periodAddCollection");if($addButtonPeriod){let $blockCollectionCall=document.getElementById("collection-period");if($blockCollectionCall){$addButtonPeriod.addEventListener("click",function(){let $addButtonPeriod=this;let newForm=$addButtonPeriod.dataset.prototype;let index=$addButtonPeriod.dataset.index*1;newForm=newForm.replace(/__periods__/g,index);let div=document.createElement("div");div.id="service_form_period_"+index;div.classList.add("mb-3");div.innerHTML=newForm;$blockCollectionCall.append(div);div.querySelector(".del-item-period")?.addEventListener("click",deletePeriod);const delButton=div.querySelector(".del-item-period");delButton.dataset.delete="service_form_period_"+index.toString();$addButtonPeriod.dataset.index=(index+1).toString();div.scrollIntoView({block:"center",inline:"center",behavior:"smooth"})})}}document.querySelectorAll(".del-item-period").forEach(function(item){item.addEventListener("click",deletePeriod)});function deletePeriod(){document.getElementById(this.dataset.delete).remove()}